const DigitalToolkit: React.FC<DigitalToolkitProps> = ({
  backgroundColor = "#070514",
  transparentBackground = false,
  durationInSeconds = 5,
  titleText = "COMENTA KIT",
  neonColor = "#00f3ff",
  toolkitColor = "#ffffff",
  hologramColor = "#df40ff",
  particleCount = 6,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? "transparent" : backgroundColor;

  // Global Animations
  const sceneScale = interpolate(frame, [0, durationInSeconds * fps], [0.9, 1.05]);
  const boxEntranceScale = spring({ frame, fps, config: { damping: 14 } });

  // Toolkit Box Constants & Animations
  const BOX_SIZE = 360;
  const OPEN_START = 20;
  const lidAngle = interpolate(frame, [OPEN_START, OPEN_START + 30], [0, 125], {
    extrapolateRight: "clamp",
    extrapolateLeft: "clamp",
  });

  const lidGlow = interpolate(frame, [OPEN_START, OPEN_START + 20], [0, 1], {
    extrapolateRight: "clamp",
    extrapolateLeft: "clamp",
  });

  // Neon Text Animations
  const TEXT_START = 60;
  const textOpacity = interpolate(frame, [TEXT_START, TEXT_START + 15], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const textScale = spring({
    frame: frame - TEXT_START,
    fps,
    config: { damping: 12 },
  });

  // Hologram Helper Render
  const renderHologram = (
    IconComponent: React.FC,
    delay: number,
    offsetX: number,
    offsetY: number,
    zTarget: number,
    size: number
  ) => {
    const scale = spring({
      frame: frame - delay,
      fps,
      config: { damping: 10 },
    });
    const zPos = spring({
      frame: frame - delay,
      fps,
      config: { damping: 12 },
    }) * zTarget;
    
    // Smooth deterministic float
    const float = Math.sin((frame - delay) / 15) * 15;
    const finalZ = zPos > 0 ? zPos + float : 0;

    return (
      <div
        style={{
          position: "absolute",
          left: "50%",
          top: "50%",
          width: 0,
          height: 0,
          transform: `translate3d(${offsetX}px, ${offsetY}px, ${finalZ}px)`,
          transition: "none",
        }}
      >
        <div
          style={{
            position: "absolute",
            left: -size / 2,
            top: -size / 2,
            width: size,
            height: size,
            // Counter rotate to face the camera + apply scale
            transform: `rotateZ(45deg) rotateX(-60deg) scale(${scale})`,
            color: hologramColor,
            filter: `drop-shadow(0 0 10px ${hologramColor}) drop-shadow(0 0 25px ${hologramColor})`,
            transition: "none",
          }}
        >
          <IconComponent />
        </div>
      </div>
    );
  };

  // Bokeh Background Particles
  const particles = Array.from({ length: particleCount }).map((_, i) => {
    const x = random(`x-${i}`) * width;
    const y = random(`y-${i}`) * height;
    const size = random(`size-${i}`) * 300 + 150;
    const speed = random(`speed-${i}`) * 2 + 1;
    const colorToggle = random(`color-${i}`) > 0.5 ? neonColor : hologramColor;
    const yOffset = Math.sin(frame / (30 * speed)) * 120;

    return (
      <div
        key={i}
        style={{
          position: "absolute",
          left: x - size / 2,
          top: y + yOffset - size / 2,
          width: size,
          height: size,
          borderRadius: "50%",
          backgroundColor: colorToggle,
          opacity: 0.12,
          filter: "blur(70px)",
          transition: "none",
        }}
      />
    );
  });

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: spaceGrotesk, overflow: "hidden" }}>
      {/* Background Layer */}
      <AbsoluteFill>{particles}</AbsoluteFill>

      {/* 3D Scene Layer */}
      <AbsoluteFill
        style={{
          perspective: 1200,
          display: "flex",
          justifyContent: "center",
          alignItems: "center",
          transform: `scale(${sceneScale}) translateY(-5%)`,
          transition: "none",
        }}
      >
        <div
          style={{
            width: BOX_SIZE,
            height: BOX_SIZE,
            transformStyle: "preserve-3d",
            transform: `scale(${boxEntranceScale}) rotateX(60deg) rotateZ(-45deg)`,
            position: "relative",
            transition: "none",
          }}
        >
          {/* Base of the Toolkit */}
          <div
            style={{
              position: "absolute",
              width: "100%",
              height: "100%",
              border: `2px solid ${toolkitColor}88`,
              backgroundColor: `${toolkitColor}11`,
              boxShadow: `inset 0 0 40px ${toolkitColor}44, 0 0 30px ${toolkitColor}22`,
              transform: "translateZ(0px)",
              transition: "none",
            }}
          />

          {/* Lid of the Toolkit */}
          <div
            style={{
              position: "absolute",
              width: "100%",
              height: "100%",
              border: `3px solid ${toolkitColor}`,
              backgroundColor: `${toolkitColor}22`,
              boxShadow: `inset 0 0 50px ${toolkitColor}66, 0 0 ${lidGlow * 40}px ${neonColor}88`,
              transformOrigin: "top",
              transform: `rotateX(${lidAngle}deg) translateZ(1px)`,
              transition: "none",
            }}
          />

          {/* Hologram Icons emerging from the box */}
          {/* Chart - Center back */}
          {renderHologram(ChartIcon, OPEN_START + 10, -30, -30, 280, 110)}
          {/* Gear - Left front */}
          {renderHologram(GearIcon, OPEN_START + 25, -100, 80, 180, 80)}
          {/* Target - Right front */}
          {renderHologram(TargetIcon, OPEN_START + 40, 80, -60, 200, 90)}
        </div>
      </AbsoluteFill>

      {/* Foreground Neon Text */}
      <AbsoluteFill
        style={{
          display: "flex",
          justifyContent: "flex-end",
          alignItems: "center",
          paddingBottom: "22%",
          pointerEvents: "none",
        }}
      >
        <div
          style={{
            opacity: textOpacity,
            transform: `scale(${textScale})`,
            color: "#ffffff",
            fontSize: 90,
            fontWeight: 800,
            letterSpacing: "0.05em",
            textAlign: "center",
            textShadow: `
              0 0 10px ${neonColor}, 
              0 0 20px ${neonColor}, 
              0 0 40px ${neonColor}, 
              0 0 80px ${neonColor}
            `,
            transition: "none",
          }}
        >
          {titleText}
        </div>
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

export default DigitalToolkit;